import{_ as a,o as i,c as o,a4 as s}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0006 — Image de base Node.js pour apps/admin : node:22-alpine","description":"Extrait de docs/adr/0006-image-base-node-admin-alpine.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0006 — Image de base Node.js pour apps/admin : node:22-alpine","description":"Extrait de docs/adr/0006-image-base-node-admin-alpine.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0006-image-base-node-admin-alpine.md","filePath":"developpeurs/adr/0006-image-base-node-admin-alpine.md"}'),t={name:"developpeurs/adr/0006-image-base-node-admin-alpine.md"};function d(n,e,r,c,l,u){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="adr-0006--image-de-base-nodejs-pour-appsadmin--node22-alpine" tabindex="-1">ADR-0006 — Image de base Node.js pour <code>apps/admin</code> : <code>node:22-alpine</code> <a class="header-anchor" href="#adr-0006--image-de-base-nodejs-pour-appsadmin--node22-alpine" aria-label="Permalink to &quot;ADR-0006 — Image de base Node.js pour `apps/admin` : `node:22-alpine` {#adr-0006--image-de-base-nodejs-pour-appsadmin--node22-alpine}&quot;">​</a></h1><p><strong>Date :</strong> 19 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> alerte &quot;Docker DX&quot; (VS Code) sur <code>apps/admin/Dockerfile</code> — image <code>node:22-slim</code>, digest <code>sha256:a17d50af28002a160548bd4225b3cfcb12c5efcb171f79e68758f2885fb1b066</code> signalée avec 3 CVE critiques et 9 CVE hautes.</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p><code>apps/admin/Dockerfile</code> utilisait <code>node:22-slim</code> (Debian bookworm) pour les deux stages (<code>build</code> et image finale). L&#39;extension Docker DX a signalé 3 CVE critiques et 9 CVE hautes sur le digest résolu au moment du scan.</p><p>Vérifications faites :</p><ul><li><strong><code>docker scout cves</code></strong> nécessite une authentification Docker Hub (<code>docker login</code>), non disponible dans cet environnement d&#39;exécution — non utilisable ici sans action de connexion du compte, écartée du périmètre de cette investigation.</li><li><strong>Le digest signalé est déjà obsolète.</strong> Un <code>docker pull node:22-slim</code> aujourd&#39;hui résout vers <code>sha256:d649c27d...</code>, différent du digest flaggé (<code>sha256:a17d50af...</code>). Docker Hub republie régulièrement le tag <code>22-slim</code> avec les correctifs de paquets Debian — une partie des CVE signalées disparaît donc déjà avec un simple rebuild sans cache, sans changement de Dockerfile.</li><li><strong>Recherche publique (Sliplane CVE scanner, sur les tags actuels)</strong> : <ul><li><code>node:22-bookworm-slim</code> : 0 critique, 4 hautes (toutes dans <code>npm</code> embarqué — <code>tar@6.2.1</code>, <code>glob@10.4.5</code> — pas dans les paquets <code>apt</code>), 2 moyennes, 25 basses.</li><li><code>node:22-alpine</code> : 0 critique, 0 haute, seulement 2 basses (busybox).</li></ul></li><li><strong>Analyse de compatibilité musl</strong> : <code>apps/admin/package.json</code> ne déclare que <code>nuxt</code> et <code>vue</code> — aucune dépendance native directe (pas de <code>sharp</code>, <code>bcrypt</code>, <code>better-sqlite3</code> en usage réel). Les dépendances transitives avec binaires précompilés (<code>esbuild</code>, <code>@parcel/watcher</code>) publient déjà des paquets musl (<code>esbuild-linux-...-musl</code>, <code>@parcel/watcher-linux-x64-musl</code>) — aucun risque de rupture attendu.</li><li><strong>Validation empirique</strong> : build Docker complet avec <code>node:22-alpine</code> sur les deux stages → succès (<code>npm install --legacy-peer-deps</code>, <code>npm run build</code>, sortie Nitro <code>.output/server/index.mjs</code> générée). Conteneur lancé localement → <code>HTTP 200</code> sur <code>/</code>.</li></ul><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Remplacer <code>node:22-slim</code> par <code>node:22-alpine</code> dans les deux stages de <code>apps/admin/Dockerfile</code>.</strong></p><p>Alpine est retenu plutôt qu&#39;une image distroless (<code>gcr.io/distroless/nodejs22-debian12</code>) car :</p><ul><li>il reste sur Docker Hub (pas de dépendance à un registre tiers supplémentaire) ;</li><li>il conserve un shell minimal utile pour le debug (<code>docker exec</code>), utile en exploitation ;</li><li>l&#39;écart de sécurité avec distroless est faible ici (le stage final ne fait déjà tourner que <code>node .output/server/index.mjs</code>, sans shell ni gestionnaire de paquets actifs au runtime) ;</li><li>c&#39;est l&#39;option la mieux établie pour un stage de build npm (compatibilité musl déjà assurée par l&#39;écosystème Vite/esbuild/Nitro utilisé par Nuxt).</li></ul><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Garder <code>node:22-slim</code>, juste forcer un rebuild sans cache</strong></td><td>Réduit une partie des CVE (digest à jour) mais ne règle pas le fond : les CVE hautes restantes (<code>tar</code>, <code>glob</code> embarqués dans npm) réapparaîtront à chaque nouvelle CVE côté Debian/npm tant que la base reste glibc + surface <code>apt</code> complète.</td></tr><tr><td><strong><code>gcr.io/distroless/nodejs22-debian12</code></strong></td><td>Surface d&#39;attaque encore plus réduite (pas de shell, pas de gestionnaire de paquets), mais registre tiers (gcr.io) hors Docker Hub, pas de shell pour le debug en exploitation, et gain marginal ici vu que le stage final n&#39;exécute déjà qu&#39;un seul binaire <code>node</code>. Piste à garder en réserve si une politique de sécurité plus stricte est adoptée plus tard.</td></tr><tr><td><strong><code>node:22-alpine</code> uniquement sur le stage final, garder <code>slim</code> pour le build</strong></td><td>Écartée : le stage <code>build</code> a la même exposition (il tourne dans le même pipeline CI/CD et peut être ciblé par une CVE npm) ; autant harmoniser les deux stages, le coût de migration est identique.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Passage de ~9 CVE hautes / 3 critiques (digest périmé) à un profil quasi nul (0 critique, 0 haute sur les tags actuels).</li><li>Image finale plus légère (~58 Mo vs ~80 Mo pour <code>node:22-slim</code> au moment du test), réduit le temps de pull/déploiement.</li><li>Alignement avec la pratique standard de l&#39;écosystème Node/Nuxt pour des builds JS purs sans dépendance native.</li></ul><p><strong>Négatives</strong></p><ul><li><code>musl</code> (Alpine) diffère légèrement de <code>glibc</code> (Debian) en comportement bas niveau ; si une dépendance native sans binaire musl est ajoutée plus tard (ex. certains drivers <code>better-sqlite3</code> compilés côté serveur), le build échouera et nécessitera l&#39;ajout de <code>python3 make g++</code> dans le stage <code>build</code> — à surveiller lors de l&#39;ajout de nouvelles dépendances.</li><li>Le digest épinglé (<code>sha256:c610fcdfb1d5b4740dd70c284ed3cb16bb857e0f7166196e36a5501df7a3aa32</code>) ne se met plus à jour automatiquement : un correctif de sécurité publié plus tard par l&#39;image officielle sur le tag <code>22-alpine</code> n&#39;est <strong>pas</strong> appliqué tant que le digest n&#39;est pas rafraîchi manuellement dans le Dockerfile. Contrepartie assumée de la reproductibilité — nécessite une revue périodique (ex. dépendabot/renovate sur les digests Docker, ou vérification manuelle lors des mises à jour Node).</li></ul><h2 id="mise-à-jour--pinning-par-digest" tabindex="-1">Mise à jour — pinning par digest <a class="header-anchor" href="#mise-à-jour--pinning-par-digest" aria-label="Permalink to &quot;Mise à jour — pinning par digest {#mise-à-jour--pinning-par-digest}&quot;">​</a></h2><p>Le tag <code>22-alpine</code> a été épinglé par digest sur les deux stages, pour la reproductibilité des builds (build identique bit-à-bit d&#39;un run CI à l&#39;autre, indépendamment des republications ultérieures du tag) :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span>FROM node:22-alpine@sha256:c610fcdfb1d5b4740dd70c284ed3cb16bb857e0f7166196e36a5501df7a3aa32</span></span></code></pre></div><p>Digest vérifié le 19 août 2026 (<code>docker pull node:22-alpine</code> → <code>Digest: sha256:c610fcdfb1d5b4740dd70c284ed3cb16bb857e0f7166196e36a5501df7a3aa32</code>). Build et démarrage du conteneur revalidés avec ce digest épinglé.</p><h2 id="mise-à-jour--rafraîchissement-automatique-via-renovate" tabindex="-1">Mise à jour — rafraîchissement automatique via Renovate <a class="header-anchor" href="#mise-à-jour--rafraîchissement-automatique-via-renovate" aria-label="Permalink to &quot;Mise à jour — rafraîchissement automatique via Renovate {#mise-à-jour--rafraîchissement-automatique-via-renovate}&quot;">​</a></h2><p>Un digest épinglé fige aussi les futurs correctifs de sécurité tant qu&#39;il n&#39;est pas rafraîchi. Pour ne pas dépendre d&#39;une revue manuelle, <code>renovate.json</code> configure Renovate sur l&#39;ensemble du dépôt (<code>config:recommended</code>) : le manager Docker de Renovate détecte les <code>FROM image@sha256:...</code> (ici <code>apps/admin/Dockerfile</code>) et ouvre une PR dès que le digest du tag suivi change en amont, sans jamais changer le tag lui-même.</p><p>Choix retenus (validés avec Bastien) :</p><ul><li><strong>Hébergement : GitHub App officielle Renovate</strong> — installation à faire côté GitHub (marketplace), aucune maintenance de token côté repo.</li><li><strong>Pas d&#39;automerge</strong> : les PR de rafraîchissement de digest (Docker + docker-compose) sont groupées et étiquetées <code>dependencies</code>, mais restent soumises à revue et merge manuels, cohérent avec la règle du dépôt de ne rien merger sans validation humaine.</li></ul><h2 id="mise-à-jour--vérification-de-lordre-copy--install-miroir-de-ladr-0007" tabindex="-1">Mise à jour — vérification de l&#39;ordre COPY / install (miroir de l&#39;ADR-0007) <a class="header-anchor" href="#mise-à-jour--vérification-de-lordre-copy--install-miroir-de-ladr-0007" aria-label="Permalink to &quot;Mise à jour — vérification de l&#39;ordre COPY / install (miroir de l&#39;ADR-0007) {#mise-à-jour--vérification-de-lordre-copy--install-miroir-de-ladr-0007}&quot;">​</a></h2><p>Même vérification que sur <code>apps/api</code> (ADR-0007) : le bug d&#39;editable install Python (paquet non enregistré si l&#39;install tourne avant que le code source existe) n&#39;a pas d&#39;équivalent direct côté npm — <code>npm install</code>/<code>npm ci</code> n&#39;ont besoin que de <code>package.json</code> (et du lockfile), jamais du code applicatif, pour installer les dépendances. Aucune casse du même type ici.</p><p>En revanche, un problème <strong>analogue en esprit</strong> a été trouvé : <code>package-lock.json</code> existe dans le repo mais n&#39;était jamais copié avant l&#39;install (<code>COPY package.json ./</code> seul) — le lockfile n&#39;était donc jamais consulté par <code>npm install</code>, qui résolvait les versions à chaque build indépendamment de ce qui est réellement figé dans le repo. Aujourd&#39;hui les versions résolues coïncident par coïncidence avec le lockfile (vérifié : <code>nuxt@3.21.11</code>, <code>vue@3.5.41</code> identiques dans les deux cas), mais rien ne garantissait que ça reste vrai à la prochaine publication d&#39;une version dans l&#39;intervalle semver — dérive silencieuse, jamais une erreur.</p><p><strong>Corrigé</strong> : <code>COPY package.json package-lock.json ./</code> puis <code>RUN npm ci --legacy-peer-deps</code> (au lieu de <code>npm install</code>). <code>npm ci</code> exploite le lockfile de façon stricte — il <strong>échoue explicitement</strong> si <code>package.json</code>/<code>package-lock.json</code> sont désynchronisés, au lieu de dériver silencieusement — et reste plus rapide qu&#39;<code>npm install</code> en environnement CI/Docker. Build et démarrage revalidés (<code>HTTP 200</code>).</p><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Modifier <code>apps/admin/Dockerfile</code> : <code>node:22-slim</code> → <code>node:22-alpine</code> sur les deux stages.</li><li>[x] Épingler <code>node:22-alpine</code> par digest sur les deux stages.</li><li>[x] Valider le build et le démarrage du conteneur en local (tag flottant puis digest épinglé).</li><li>[x] Ajouter <code>renovate.json</code> pour le rafraîchissement automatique des digests Docker (PR manuelle, pas d&#39;automerge).</li><li>[x] Copier <code>package-lock.json</code> avant l&#39;install et passer à <code>npm ci --legacy-peer-deps</code> (lockfile jamais honoré auparavant).</li><li>[ ] Installer la GitHub App Renovate sur le dépôt (action GitHub, à faire par Bastien).</li><li>[ ] Relancer un scan Docker Scout authentifié (<code>docker login</code> puis <code>docker scout cves</code>) une fois l&#39;accès disponible, pour confirmer l&#39;extinction de l&#39;alerte sur le digest réellement déployé.</li></ul>',31)])])}const g=a(t,[["render",d]]);export{m as __pageData,g as default};
